import hashlib,json,os,statistics,subprocess,time,shutil
from pathlib import Path
os.sched_setaffinity(0,{0})
target=Path('docs/review-performance/J21.json')
work=Path('build/review-j21-performance');work.mkdir(exist_ok=True)
def digest(path):
 with open(path,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
data={'parent_commit':'72a0356','protocol':'3 alternating pairs, CPU0, no other own builds/tests. Each non-LTO batch runs 20 unchanged all+debug builds; each default LTO batch runs 3 unchanged all builds. Parent and candidate use the same prepared artifacts within each mode. Every individual child duration and peak RSS is recorded. Batch RSS is the maximum of child peaks, not a sum. No algorithm source changes; executable hashes are compared directly.', 'runs':[], 'summary':[], 'blocked':None, 'setup_note':'Initial launcher invocation used make without an absolute path. posix_spawn (not posix_spawnp) returned before launching any build; no performance sample was collected. Use shutil.which to resolve the executable.'}
data['binary_hashes']={str(p):digest(p) for directory in ('review-j20','review-j21') for name in ('mus-solver','mus-bot','mus-match-eval') for p in [Path('build')/directory/'release'/name]}
def save():
 data['script']=Path(__file__).read_text();data['parent_makefile']=Path('/tmp/mus-j21-parent.mk').read_text();data['launcher_source']=Path('/tmp/mus-review-j12-measure.c').read_text();target.write_text(json.dumps(data,indent=2)+'\n')
for mode,n in [('non-lto',20),('lto',3)]:
 directory='build/review-j21-bench'+('-lto' if mode=='lto' else '')
 args=[f'BUILD_DIR={directory}',f'CFR_BUILD_DIR={directory}']
 args += ['all'] if mode=='lto' else ['RELEASE_LTO_FLAGS=','RELEASE_LINK_FLAGS=','all','debug']
 binaries=[p for p in Path(directory).rglob('*') if p.is_file() and os.access(p,os.X_OK)]
 reference={str(p):digest(p) for p in binaries}
 def pair(repeat):
  for version in (('parent','candidate') if repeat%2 else ('candidate','parent')):
   command=[shutil.which('make'),'-s','-j4','-f','/tmp/mus-j21-parent.mk' if version=='parent' else 'Makefile',*args]
   samples=[]
   for i in range(n):
    rss=work/'rss.txt';start=time.perf_counter();p=subprocess.run(['/tmp/mus-review-j12-measure',str(rss),*command],capture_output=True,text=True);wall=time.perf_counter()-start
    assert p.returncode==0,(command,p.stdout,p.stderr)
    samples.append({'seconds':wall,'peak_rss_kib':int(rss.read_text())})
   hashes={str(p):digest(p) for p in binaries};assert hashes==reference
   row={'mode':mode,'version':version,'repeat':repeat,'command':command,'count':n,'wall_seconds':sum(r['seconds'] for r in samples),'peak_rss_kib':max(r['peak_rss_kib'] for r in samples),'samples':samples,'binary_hashes':hashes}
   data['runs'].append(row);save();print(mode,version,repeat,row['wall_seconds'],row['peak_rss_kib'],flush=True)
 def summary(confirm=False):
  rows=[r for r in data['runs'] if r['mode']==mode and (r['repeat']>3)==confirm];s={'mode':mode,'confirmation':confirm,'batch_count':n}
  for field in ('wall_seconds','peak_rss_kib'):
   a=statistics.median(r[field] for r in rows if r['version']=='parent');b=statistics.median(r[field] for r in rows if r['version']=='candidate');s[field]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
  s['trigger']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
  data['summary'].append(s);save();print(s,flush=True);return s['trigger']
 for repeat in range(1,4):pair(repeat)
 if summary():
  for repeat in range(4,9):pair(repeat)
  if summary(True):data['blocked']=mode;save();raise SystemExit(2)
save()

